import re

def parse_size(text):
    pattern = r'^\b([0-9]+)([BbKkMmGg])$'
    match = re.match(pattern, text)

    if match:
        number, unit = match.groups()
        number = int(number)
        if unit.upper() == 'B':
            multiplier = 1
        elif unit.upper() == 'KB':
            multiplier = 1024
        elif unit.upper() == 'MB':
            multiplier = 1024**2
        elif unit.upper() == 'GB':
            multiplier = 1024**3
        else:
            raise ValueError("Unknown unit")
        return number * multiplier
    else:
        raise ValueError("Invalid input")

