import heapq

class TaskQueue:
    def __init__(self):
        self._tasks = []
        self._names = set()

    def add(self, name, priority):
        if name in self._names:
            raise ValueError("Task with name already exists")
        heapq.heappush(self._tasks, (priority, name))
        self._names.add(name)

    def pop(self):
        if not self._tasks:
            raise IndexError("Queue is empty")
        _, name = heapq.heappop(self._tasks)
        self._names.remove(name)
        return name

    def __len__(self):
        return len(self._tasks)

