class TaskQueue:
    def __init__(self):
        self._tasks = []
        self._task_names = set()

    def add(self, name, priority):
        if name in self._task_names:
            raise ValueError("Task name already exists")
        heapq.heappush(self._tasks, (priority, name))
        self._task_names.add(name)

    def pop(self):
        if not self._tasks:
            raise IndexError("Queue is empty")
        priority, name = heapq.heappop(self._tasks)
        self._task_names.remove(name)
        return name

